/**
 * Videos API - 视听中心视频接口
 * 
 * 接口列表:
 * - getVideos: 获取所有视频 (支持筛选)
 * - getVideoDetail: 获取单个视频详情
 * - getCategories: 获取视频分类
 */

import request from './request.js'

export default {
  /**
   * 获取所有视频
   * @param {object} params - 查询参数 { category, search, page, limit }
   */
  getVideos(params = {}) {
    return request.get('/videos', { params })
  },

  /**
   * 获取单个视频详情
   * @param {string} id - 视频ID
   */
  getVideoDetail(id) {
    return request.get(`/videos/${id}`)
  },

  /**
   * 获取视频分类
   */
  getCategories() {
    return request.get('/videos/categories')
  }
}
